import type { BenchmarkTask } from './types.js';
import { finalReplyContains, finalReplyContainsNumbers } from './checks.js';

/**
 * The fixed benchmark task set (see specs/agent-benchmark/spec.md - "The
 * benchmark task set is fixed and declares correctness"). Once a baseline
 * snapshot has been taken, DO NOT EDIT this file (see README.md - "The task
 * set is frozen once a baseline exists"): editing a task's id, kind, turns,
 * or check changes the task set's identity (`task-set-id.ts`), and
 * `compare.ts` refuses to diff snapshots whose task-set identity differs
 * rather than presenting the difference as though it were the effect of an
 * unrelated change.
 *
 * Each task is deliberately checkable (a computed value, a specific file's
 * content, a number the runner can verify independently) rather than
 * open-ended, because correctness here is decided mechanically, never by a
 * model's judgement - see design.md - Decisions.
 */
export const BENCHMARK_TASKS: BenchmarkTask[] = [
  {
    id: 'capital-of-france',
    kind: 'no-tools',
    turns: ['What is the capital of France? Reply with just the city name, nothing else.'],
    check: finalReplyContains('paris'),
  },
  {
    id: 'shell-arithmetic',
    kind: 'command',
    turns: [
      'Use a shell command to compute 384726 + 918273 (for example `echo $((384726+918273))`), then reply with just the resulting number.',
    ],
    check: finalReplyContainsNumbers([1302999]),
  },
  {
    id: 'read-os-release',
    kind: 'file-read',
    turns: [
      'Read the file /etc/os-release inside your sandbox and reply with just the value of its ID field (for example "alpine"), nothing else.',
    ],
    check: finalReplyContains('alpine'),
  },
  {
    id: 'word-count-skill',
    kind: 'skill',
    turns: [
      'Use the word-count skill to count the words in this exact sentence: "the quick brown fox jumps over the lazy dog". Reply with just the number.',
    ],
    check: finalReplyContainsNumbers([9]),
  },
  {
    id: 'subagent-three-sums',
    kind: 'subagent',
    turns: [
      'Use your sub-agent tool to independently compute these three sums: 12+7, 100-58, and 6*9. Do not pass a "model" argument to the sub-agent tool - omit it entirely so the default model is used. Reply with all three results, in order, separated by commas.',
    ],
    check: finalReplyContainsNumbers([19, 42, 54]),
  },
  {
    id: 'remember-favorite-number',
    kind: 'multi-turn',
    turns: [
      'My favorite number is 27. Just acknowledge that you noted it - do not do anything else.',
      'What is my favorite number plus 15? Reply with just the number.',
    ],
    check: finalReplyContainsNumbers([42]),
  },
];
